 public static Uri AllowedUri(string url){if(!Uri.TryCreate(url,UriKind.Absolute,out var u)||u.Scheme!="https"||!u.IsDefaultPort||u.UserInfo!=""||u.Host is not("api.modrinth.com" or "cdn.modrinth.com" or "github.com" or "raw.githubusercontent.com" or "gitlab.com" or "release-assets.githubusercontent.com" or "objects.githubusercontent.com" or "meta.fabricmc.net" or "meta.quiltmc.org" or "maven.fabricmc.net" or "maven.quiltmc.org" or "maven.minecraftforge.net" or "maven.neoforged.net" or "libraries.minecraft.net"))throw new InvalidDataException("Unsupported modpack download host: "+url);return u;}
