 public static PackIndex ParseIndex(JsonNode data){if(data["formatVersion"]?.GetValue<int>()!=1||S(data,"game")!="minecraft")throw new InvalidDataException("Unsupported MRPACK format.");var deps=data["dependencies"]?.AsObject()??throw new InvalidDataException("Missing pack dependencies.");string mc=S(deps,"minecraft");MojangInstaller.ValidateId(mc);if(deps.Any(d=>d.Key is not("minecraft" or "fabric-loader" or "quilt-loader" or "forge" or "neoforge")))throw new InvalidDataException("Unknown modpack loader dependency.");var loaders=deps.Where(d=>d.Key!="minecraft").ToArray();if(loaders.Length>1)throw new InvalidDataException("Multiple pack loaders.");string loader=loaders.FirstOrDefault().Key??"",version=loaders.FirstOrDefault().Value?.ToString()??"";if(version!="")MojangInstaller.ValidateId(version);
 var files=new List<PackFile>();var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;foreach(var f in data["files"]?.AsArray()??new JsonArray()){if(S(f?["env"],"client")=="unsupported")continue;string path=S(f,"path");ContentPath(System.IO.Path.GetTempPath(),path);if(!paths.Add(path))throw new InvalidDataException("Duplicate pack path.");string hash=S(f?["hashes"],"sha512");if(!Regex.IsMatch(hash,"^[a-fA-F0-9]{128}$"))throw new InvalidDataException("Missing pack SHA-512.");long size=long.TryParse(S(f,"fileSize"),out var fileSize)?fileSize:-1;if(size<=0||size>512L*1024*1024||(total+=size)>8L*1024*1024*1024||files.Count>=4096)throw new InvalidDataException("Modpack size limit exceeded.");var urls=f?["downloads"]?.AsArray()??throw new InvalidDataException("Missing mod download.");string? url=urls.Select(u=>u!.ToString()).FirstOrDefault(u=>{try{var uri=AllowedUri(u);return uri.Host is "cdn.modrinth.com" or "github.com" or "raw.githubusercontent.com" or "gitlab.com";}catch{return false;}});if(url==null)throw new InvalidDataException("No supported download source.");files.Add(new(path,url,hash,size));}return new(S(data,"name"),mc,loader,version,files);}
 async Task Download(string url,string path,string hash,long size,HashAlgorithmName algorithm,Action<long>? advance,CancellationToken ct){Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path)!);using var response=await Get(url,ct);using var input=await response.Content.ReadAsStreamAsync(ct);using var output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None,131072,true);using var digest=IncrementalHash.CreateHash(algorithm);byte[] bytes=new byte[131072];long count=0;int n;while((n=await input.ReadAsync(bytes,ct))>0){count+=n;if(count>size)throw new IOException("Modpack download size mismatch.");digest.AppendData(bytes,0,n);await output.WriteAsync(bytes.AsMemory(0,n),ct);advance?.Invoke(n);}if(count!=size||!Convert.ToHexString(digest.GetHashAndReset()).Equals(hash,StringComparison.OrdinalIgnoreCase))throw new IOException("Modpack download checksum mismatch.");}
 public static void ExtractOverrides(string archive,string root,CancellationToken ct=default){using var zip=ZipFile.OpenRead(archive);if(zip.Entries.Count>12000)throw new InvalidDataException("Too many override files.");long total=0;foreach(string prefix in new[]{"overrides/","client-overrides/"}){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in zip.Entries.Where(e=>e.FullName.StartsWith(prefix,StringComparison.Ordinal)&&e.Name!="")){ct.ThrowIfCancellationRequested();string name=entry.FullName[prefix.Length..];string target=ContentPath(root,name);if(!seen.Add(name)||entry.Length>512L*1024*1024||(total+=entry.Length)>4L*1024*1024*1024||((entry.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Invalid or oversized pack override.");Directory.CreateDirectory(System.IO.Path.GetDirectoryName(target)!);using var source=entry.Open();using var dest=File.Create(target);source.CopyTo(dest);}}}
 public async Task<VersionEntry> InstallAsync(ModProject project,IProgress<ModProgress>? progress=null,CancellationToken ct=default){if(!Regex.IsMatch(project.Id,"^[a-zA-Z0-9_-]{1,160}$"))throw new InvalidDataException("Invalid project ID.");var releases=(await Json("https://api.modrinth.com/v2/project/"+project.Id+"/version?include_changelog=false",ct)).AsArray();var release=releases.Where(n=>S(n,"status") is not("draft" or "scheduled")).OrderBy(n=>S(n,"version_type")=="release"?0:1).ThenByDescending(n=>S(n,"date_published")).FirstOrDefault()??throw new IOException("No published modpack versions.");var f=release["files"]!.AsArray().FirstOrDefault(f=>S(f,"filename").EndsWith(".mrpack",StringComparison.OrdinalIgnoreCase))??throw new InvalidDataException("Missing MRPACK archive.");long size=f["size"]!.GetValue<long>();if(size<=0||size>512L*1024*1024)throw new InvalidDataException("MRPACK archive is too large.");string hash=S(f["hashes"],"sha512");if(!Regex.IsMatch(hash,"^[a-fA-F0-9]{128}$"))throw new InvalidDataException("Missing archive hash.");string releaseId=S(release,"id");var existing=Scan(installRoot).FirstOrDefault(v=>{var p=JsonSerializer.Deserialize<InstalledPack>(File.ReadAllText(System.IO.Path.Combine(v.RootOverride!,".orbit-pack.json")));return p?.Project==project.Id&&p.Release==releaseId;});if(existing!=null)return existing;
 Directory.CreateDirectory(installRoot);string token=Guid.NewGuid().ToString("N"),stage=Versions.Within(installRoot,".staging-"+token),final=Versions.Within(installRoot,token);Directory.CreateDirectory(stage);string archive=System.IO.Path.Combine(stage,"pack.mrpack");try{long received=0;progress?.Report(new("Downloading modpack",0,size));await Download(S(f,"url"),archive,hash,size,HashAlgorithmName.SHA512,n=>{received+=n;progress?.Report(new("Downloading modpack",received,size));},ct);PackIndex index;using(var zip=ZipFile.OpenRead(archive)){var entry=zip.GetEntry("modrinth.index.json")??throw new InvalidDataException("Missing modrinth.index.json.");if(entry.Length>24*1024*1024)throw new InvalidDataException("Pack index is too large.");using var reader=new StreamReader(entry.Open());index=ParseIndex(JsonNode.Parse(await reader.ReadToEndAsync(ct))!);}
