 }catch{if(Directory.Exists(stage)&&System.IO.Path.GetFullPath(stage).StartsWith(System.IO.Path.GetFullPath(installRoot)+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&System.IO.Path.GetFileName(stage)==".staging-"+token)Directory.Delete(stage,true);throw;}}
 public async Task<string> InstallLoaderAsync(string root,PackIndex index,IProgress<ModProgress>? progress,CancellationToken ct){if(index.Loader=="")return index.Minecraft;progress?.Report(new("Installing "+index.Loader,0,0));if(index.Loader is "fabric-loader" or "quilt-loader"){bool fabric=index.Loader=="fabric-loader";string endpoint=fabric?"https://meta.fabricmc.net/v2/versions/loader/":"https://meta.quiltmc.org/v3/versions/loader/";var profile=await Json(endpoint+Uri.EscapeDataString(index.Minecraft)+"/"+Uri.EscapeDataString(index.LoaderVersion)+"/profile/json",ct);string id=S(profile,"id");MojangInstaller.ValidateId(id);string folder=Versions.Within(root,"versions/"+id);Directory.CreateDirectory(folder);await File.WriteAllTextAsync(System.IO.Path.Combine(folder,id+".json"),profile.ToJsonString(),ct);
 foreach(var lib in profile["libraries"]?.AsArray()??new JsonArray()){if(lib==null||!LaunchEngine.Allowed(lib["rules"]))continue;string name=S(lib,"name"),path=LaunchEngine.MavenPath(name);string url=S(lib,"url");if(url=="")url="https://libraries.minecraft.net/";url=url.TrimEnd('/')+"/"+path;var artifact=lib["downloads"]?["artifact"];if(artifact!=null)url=S(artifact,"url");string target=Versions.Within(root,"libraries/"+path);if(File.Exists(target))continue;string sha=artifact?["sha1"]?.ToString()??System.Text.Encoding.UTF8.GetString(await Bytes(url+".sha1",4096,ct)).Trim().Split(' ')[0];if(!Regex.IsMatch(sha,"^[a-fA-F0-9]{40}$"))throw new InvalidDataException("Missing loader library checksum.");byte[] bytes=await Bytes(url,128*1024*1024,ct);if(!Convert.ToHexString(SHA1.HashData(bytes)).Equals(sha,StringComparison.OrdinalIgnoreCase))throw new IOException("Loader library checksum mismatch.");Directory.CreateDirectory(System.IO.Path.GetDirectoryName(target)!);await File.WriteAllBytesAsync(target,bytes,ct);}return id;}
 bool neo=index.Loader=="neoforge";string build=neo?index.LoaderVersion:index.Minecraft+"-"+index.LoaderVersion;string baseUrl=neo?"https://maven.neoforged.net/releases/net/neoforged/neoforge/":"https://maven.minecraftforge.net/net/minecraftforge/forge/";string name2=neo?"neoforge":"forge";string installerUrl=baseUrl+build+"/"+name2+"-"+build+"-installer.jar";string expected=System.Text.Encoding.UTF8.GetString(await Bytes(installerUrl+".sha1",4096,ct)).Trim().Split(' ')[0];byte[] installer=await Bytes(installerUrl,64*1024*1024,ct);if(!Regex.IsMatch(expected,"^[a-fA-F0-9]{40}$")||!Convert.ToHexString(SHA1.HashData(installer)).Equals(expected,StringComparison.OrdinalIgnoreCase))throw new IOException("Loader installer checksum mismatch.");string jar=System.IO.Path.Combine(root,".loader-installer.jar");await File.WriteAllBytesAsync(jar,installer,ct);await File.WriteAllTextAsync(System.IO.Path.Combine(root,"launcher_profiles.json"),"{\"profiles\":{}}",ct);int major=Versions.Resolve(root,index.Minecraft).JavaMajor;var java=LaunchEngine.FindJava(root,major)??throw new IOException("Java runtime not available for loader.");var start=new ProcessStartInfo(java.Path){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string arg in new[]{"-jar",jar,"--installClient",root})start.ArgumentList.Add(arg);using var p=Process.Start(start)??throw new IOException("Loader installer failed to start.");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromMinutes(12));var output=p.StandardOutput.ReadToEndAsync(timeout.Token);var errors=p.StandardError.ReadToEndAsync(timeout.Token);try{await p.WaitForExitAsync(timeout.Token);await Task.WhenAll(output,errors);}catch{if(!p.HasExited)p.Kill(true);await p.WaitForExitAsync(CancellationToken.None);throw;}if(p.ExitCode!=0)throw new IOException("Loader installer failed (exit "+p.ExitCode+"). Try a different modpack version.");File.Delete(jar);File.Delete(System.IO.Path.Combine(root,"launcher_profiles.json"));return Versions.Scan(root).FirstOrDefault(v=>neo?v.Loader=="NeoForge":v.Loader=="Forge")?.Id??throw new IOException("Loader did not create a profile.");
